// Source-selected red rubric mixed alphabet, all primitive q8 keys,
// latent word boundaries. Two disjoint full-period lexical anchors
// suffice to enumerate a key; exact minimum-OOV segmentation follows.
#include <bits/stdc++.h>
using namespace std;
using U=uint64_t;using A=array<int,29>;using K=array<int,8>;
const string sy="0123456789abcdefghijklmnopqrs";
const vector<string> rn={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
int md(int x){return (x+29)%29;}
string file(const string&p){ifstream f(p);if(!f)throw runtime_error(p);return string(istreambuf_iterator<char>(f),{});}
vector<string> words(const string&s){istringstream f(s);vector<string>v;string w;while(f>>w)v.push_back(w);return v;}
vector<string> fields(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\"([^\"]*)\"");vector<string>v;for(sregex_iterator i(s.begin(),s.end(),re),e;i!=e;++i)v.push_back((*i)[1]);return v;}
vector<string> arrfield(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\\[([^\\]]*)\\]");smatch m;if(!regex_search(s,m,re))throw runtime_error(k);string t=m[1];regex z("\"([0-9a-s]+)\"");vector<string>v;for(sregex_iterator i(t.begin(),t.end(),z),e;i!=e;++i)v.push_back((*i)[1]);return v;}
map<string,double> freq;double fcur=0,totalFreq=0;
struct Node{array<int,29> next{};int word=-1;Node(){next.fill(-1);}};
vector<Node> trie(1);vector<string> lex;vector<double> logp;vector<vector<pair<string,vector<int>>>> by(64);int maxlen=0;
void spell(const string&s,int i,string w){if(i==(int)s.size()){freq[w]+=fcur;return;}for(int n=1;n<=3&&i+n<=(int)s.size();n++){string t=s.substr(i,n);int j=-1;if(n==3){if(t=="ING")j=21;}else for(int x=0;x<29;x++)if(t==rn[x]){j=x;break;}if(j>=0)spell(s,i+n,w+sy[j]);}}
void dictionary(){istringstream f(file("resources/control/english_wordfreq_textblob.txt"));string l;regex re("^([a-z]+)\\s+([0-9]+)$");smatch m;while(getline(f,l)){if(!regex_match(l,m,re))continue;string s=m[1],v,z;fcur=stod(m[2]);for(char c:s)v+=toupper(c);for(int i=0;i<(int)v.size();i++){if(v.substr(i,2)=="QU"){z+="CW";i++;continue;}char c=v[i];z+=c=='V'?'U':c=='K'||c=='Q'?'C':c=='Z'?'S':c;}spell(z,0,"");}if(freq.size()!=38910)throw runtime_error("base dictionary");for(auto&w:words(fields(file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json"),"added").at(0)))if(!freq.count(w))freq[w]=1;if(freq.size()!=38938)throw runtime_error("dictionary");for(auto&[w,v]:freq)totalFreq+=v+0.1;for(auto&[w,v]:freq){int id=lex.size(),q=0;lex.push_back(w);logp.push_back(log((v+0.1)/totalFreq));vector<int> a;for(char c:w){int x=sy.find(c);a.push_back(x);int n=trie[q].next[x];if(n<0){n=trie.size();trie[q].next[x]=n;trie.emplace_back();}q=n;}trie[q].word=id;maxlen=max(maxlen,(int)w.size());by[w.size()].push_back({w,move(a)});}}
vector<A> bank;vector<string> labels;
void alphabets(){for(string w:{"jlnr2eaj","ojlnr2eaj"})for(int f=0;f<2;f++){string order;if(f)order+='0';for(char c:w+sy)if(order.find(c)==string::npos)order+=c;A p{};int z=order.find('0');for(int x=0;x<29;x++)p[x]=md((int)order.find(sy[x])-z);if(find(bank.begin(),bank.end(),p)==bank.end()){bank.push_back(p);labels.push_back(w+(f?":F-first":":rotate"));}}}
U norm(const K&k){int best=0;for(int i=1;i<8;i++)for(int j=0;j<8;j++){int a=k[(i+j)&7],b=k[(best+j)&7];if(a<b){best=i;break;}if(a>b)break;}U x=0;for(int j=0;j<8;j++)x=x*29+k[(best+j)&7];return x;}
K unpack(U x){K k;for(int j=7;j>=0;j--){k[j]=x%29;x/=29;}return k;}
bool primitive(const K&k){for(int j=0;j<4;j++)if(k[j]!=k[j+4])return true;return false;}
string encrypt(const string&w,const A&p,const K&k,int j){A ip{};for(int x=0;x<29;x++)ip[p[x]]=x;string c;for(char x:w){int a=sy.find(x);if(!a)c+='0';else{c+=sy[ip[md(p[a]+k[j])]];j=(j+1)&7;}}return c;}
struct Edge{int len,id,phase;};using ED=vector<vector<Edge>>;
ED edges(const string&C,const A&p,const K&k){A ip{};for(int x=0;x<29;x++)ip[p[x]]=x;int mp[8][29];for(int j=0;j<8;j++)for(int x=0;x<29;x++)mp[j][x]=ip[md(p[x]-k[j])];ED out(C.size());for(int start=0;start<(int)C.size();start++){vector<Edge> best(maxlen+1,{-1,-1,-1});for(int phase=0;phase<8;phase++){function<void(int,int,int)> walk=[&](int i,int j,int node){int n=i-start,id=trie[node].word;if(id>=0&&(best[n].id<0||logp[id]>logp[best[n].id]))best[n]={n,id,phase};if(i==(int)C.size()||n==maxlen)return;int x=sy.find(C[i]);if(x==0&&trie[node].next[0]>=0)walk(i+1,j,trie[node].next[0]);int y=mp[j][x];if(y&&trie[node].next[y]>=0)walk(i+1,(j+1)&7,trie[node].next[y]);};walk(start,phase,0);}for(auto e:best)if(e.id>=0){if(encrypt(lex[e.id],p,k,e.phase)!=C.substr(start,e.len))throw runtime_error("edge replay");out[start].push_back(e);}}return out;}
bool truthword(const string&c,const string&t,const A&p,const K&k){for(int j=0;j<8;j++)if(encrypt(t,p,k,j)==c)return true;return false;}
struct Cell{int bad=1000000;double score=-1e100;int prev=-1,word=-2,phase=-1;};
struct Seg{int bad=1000000,count=0,oov=0;double score=-1e100;vector<string> text;};
Seg segment(const string&C,const A&p,const K&k,int lo,int hi,int maxOOV){auto E=edges(C,p,k);int n=C.size(),D=hi+1,B=maxOOV+1;vector<Cell> dp((n+1)*D*B);auto at=[&](int i,int w,int b){return (i*D+w)*B+b;};dp[0]={0,0,-1,-2,-1};auto upd=[&](int q,int r,int bad,double sc,int word,int phase){auto&x=dp[r];if(bad<x.bad||(bad==x.bad&&sc>x.score))x={bad,sc,q,word,phase};};for(int i=0;i<n;i++)for(int w=0;w<hi;w++)for(int b=0;b<B;b++){int q=at(i,w,b);auto z=dp[q];if(z.bad==1000000)continue;for(auto e:E[i])upd(q,at(i+e.len,w+1,b),z.bad,z.score+logp[e.id],e.id,e.phase);if(b<maxOOV)for(int m=1;m<=13&&i+m<=n;m++)upd(q,at(i+m,w+1,b+1),z.bad+m,z.score-6*m-8,-1,-1);}
Seg s;int q=-1;for(int w=lo;w<=hi;w++)for(int b=0;b<B;b++){int r=at(n,w,b);auto z=dp[r];if(z.bad<s.bad||(z.bad==s.bad&&z.score>s.score)){s.bad=z.bad;s.score=z.score;s.count=w;s.oov=b;q=r;}}if(q<0||s.bad==1000000)return s;while(dp[q].prev>=0){auto z=dp[q];int end=q/(D*B),start=z.prev/(D*B);if(z.word<0)s.text.push_back("["+C.substr(start,end-start)+"]");else{s.text.push_back(lex[z.word]);if(encrypt(lex[z.word],p,k,z.phase)!=C.substr(start,end-start))throw runtime_error("segment replay");}q=z.prev;}reverse(s.text.begin(),s.text.end());return s;}
struct Candidate{int alphabet,anchors;U key;Seg fit;};
struct Stats{U trials=0,keyInc=0,distinct=0;int maxAnchors=0,candidates=0;vector<Candidate> fits;};
Stats recover(const string&C){Stats s;vector<int> c;for(char x:C)c.push_back(sy.find(x));for(int b=0;b<(int)bank.size();b++){auto&p=bank[b];unordered_map<U,uint32_t> state;state.reserve(2500000);for(int end=8;end<=(int)c.size();end++)for(int L=8;L<=min(maxlen,end);L++){int start=end-L;int nz=0;for(int j=start;j<end;j++)nz+=c[j]!=0;if(nz<8)continue;for(auto&item:by[L]){s.trials++;auto&w=item.second;K k;k.fill(-1);int j=0;bool ok=true;for(int i=0;i<L;i++){if(!w[i]){if(c[start+i]){ok=false;break;}continue;}int d=md(p[c[start+i]]-p[w[i]]);int h=j&7;if(k[h]>=0&&k[h]!=d){ok=false;break;}k[h]=d;j++;}if(!ok||j<8||!primitive(k))continue;s.keyInc++;U id=norm(k);auto&x=state[id];int last=x&65535,count=x>>16;if(start>=last){count++;x=(count<<16)|end;s.maxAnchors=max(s.maxAnchors,count);}}}s.distinct+=state.size();for(auto [id,x]:state)if((x>>16)>=2){s.candidates++;K k=unpack(id);Seg a=segment(C,p,k,40,55,3);if(a.bad<=21)s.fits.push_back({b,int(x>>16),id,move(a)});}}
sort(s.fits.begin(),s.fits.end(),[](auto&a,auto&b){if(a.fit.bad!=b.fit.bad)return a.fit.bad<b.fit.bad;if(a.fit.score!=b.fit.score)return a.fit.score>b.fit.score;if(a.alphabet!=b.alphabet)return a.alphabet<b.alphabet;return a.key<b.key;});return s;}
template<class T>string ar(const T&v){string s="[";for(auto x:v){if(s.size()>1)s+=",";s+=to_string(x);}return s+"]";}
string joined(const vector<string>&v){string s;for(auto&w:v)s+=w;return s;}
string strarr(const vector<string>&v){string s="[";for(auto&w:v){if(s.size()>1)s+=",";s+='"'+w+'"';}return s+"]";}
int main(int argc,char**argv){dictionary();alphabets();string mode=argc>1?argv[1]:"0";bool control=mode!="original";auto f=file("resources/liber-primus/lp2-page-groups-54-55-derived.json");auto ct=arrfield(f,"body_groups"),ht=arrfield(f,"groups");ht[0]=ct.back()+ht[0];ct.pop_back();if(ct.size()!=47||ht.size()!=17||joined(ct).size()!=213||joined(ht).size()!=86)throw runtime_error("terminal profile");vector<string>T,H,TC,HC;A tp{};K tk{};int tb=-1;vector<int>omit;
if(control){int i=stoi(mode);if(i<0||i>1)throw runtime_error("mode");auto f2=file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json");auto tt=words(fields(f2,"truth").at(i));if(tt.size()!=65)throw runtime_error("truth size");mt19937 rng(0x29fa8a10u+i);T.assign(tt.begin(),tt.begin()+47);H.push_back(by[11][rng()%by[11].size()].first);H.insert(H.end(),tt.begin()+49,tt.end());tb=i==0?0:(int)bank.size()-1;tp=bank[tb];for(int j=0;j<8;j++)tk[j]=rng()%29;if(!primitive(tk))throw runtime_error("period");vector<int> elig;for(int j=0;j<47;j++)if(T[j].size()>=8)elig.push_back(j);shuffle(elig.begin(),elig.end(),rng);omit.assign(elig.begin(),elig.begin()+3);sort(omit.begin(),omit.end());for(int j=0;j<47;j++){if(find(omit.begin(),omit.end(),j)!=omit.end()){T[j].clear();for(int z=0;z<(int)ct[j].size();z++)T[j]+=sy[1+rng()%28];}TC.push_back(encrypt(T[j],tp,tk,rng()%8));}for(auto&w:H)HC.push_back(encrypt(w,tp,tk,rng()%8));}
else{TC=ct;HC=ht;}
string C=joined(TC),Z=joined(HC);auto R=recover(C);ostringstream o;o<<"{\"mode\":\""<<mode<<"\",\"bank\":"<<bank.size()<<",\"dictionary\":"<<lex.size()<<",\"trials\":"<<R.trials<<",\"anchor_incidences\":"<<R.keyInc<<",\"distinct_keys\":"<<R.distinct<<",\"max_disjoint_anchors\":"<<R.maxAnchors<<",\"two_anchor_candidates\":"<<R.candidates<<",\"fit_count\":"<<R.fits.size()<<",\"omitted\":"<<ar(omit)<<",\"fits\":[";int rank=-1,heldTruth=0;int limit=min(20,(int)R.fits.size());for(int i=0;i<(int)R.fits.size();i++){auto&x=R.fits[i];if(control&&x.alphabet==tb&&x.key==norm(tk)){rank=i+1;for(int j=0;j<(int)H.size();j++)heldTruth+=truthword(HC[j],H[j],bank[x.alphabet],unpack(x.key));}if(i>=limit)continue;auto d=segment(Z,bank[x.alphabet],unpack(x.key),12,22,3);if(i)o<<",";o<<"{\"alphabet\":"<<x.alphabet<<",\"label\":\""<<labels[x.alphabet]<<"\",\"pi\":"<<ar(bank[x.alphabet])<<",\"key\":"<<ar(unpack(x.key))<<",\"anchors\":"<<x.anchors<<",\"train_bad\":"<<x.fit.bad<<",\"train_oov\":"<<x.fit.oov<<",\"train_words\":"<<x.fit.count<<",\"train_score\":"<<x.fit.score<<",\"held_bad\":"<<d.bad<<",\"held_words\":"<<d.count<<",\"held_score\":"<<d.score<<",\"train_path\":"<<strarr(x.fit.text)<<",\"held_path\":"<<strarr(d.text)<<"}";}o<<"],\"exact_rank\":"<<rank<<",\"held_truth\":"<<heldTruth<<"}";cout<<"FINAL "<<o.str()<<endl;if(const char*p=getenv("SFT_OUTPUT")){ofstream f(p);f<<o.str()<<endl;}return 0;}
